class Solution {
  public int[] avoidFlood(int[] rains) {
    int n = rains.length;
    int[] ans = new int[n];
    Map<Integer, Integer> lastRain = new HashMap<>();
    TreeSet<Integer> dryDays = new TreeSet<>();
    for (int i = 0; i < n; i++) {
      int lake = rains[i];
      if (lake == 0) {
        dryDays.add(i);
        ans[i] = 1;
        continue;
      }
      ans[i] = -1;
      Integer previous = lastRain.put(lake, i);
      if (previous != null) {
        // dry this lake on the first dry day after it last filled
        Integer day = dryDays.higher(previous);
        if (day == null) return new int[0];
        ans[day] = lake;
        dryDays.remove(day);
      }
    }
    return ans;
  }
}
